import sys

def main():
    input = sys.stdin.readline
    n, a, b = map(int, input().split())
    groups = list(map(int, input().split()))

    # a: free one-seat tables
    # b: free two-seat tables
    # half: two-seat tables currently occupied by one person (one seat left)
    half = 0
    denied = 0

    for t in groups:
        if t == 2:
            if b > 0:
                b -= 1
            else:
                denied += 2
        else:
            if a > 0:
                a -= 1
            elif b > 0:
                b -= 1
                half += 1
            elif half > 0:
                half -= 1
            else:
                denied += 1

    print(denied)

if __name__ == "__main__":
    main()
